a:
Middleware trong Go là một wrapper function nhận handler và trả về handler mới, cho phép chèn logic trước hoặc sau khi xử lý request.
```go
 // Middleware cơ bản — stdlib net/http
func authMiddleware(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        token := r.Header.Get("Authorization")
        if !isValidToken(token) {
            http.Error(w, "Unauthorized", http.StatusUnauthorized)
            return
        }
        next.ServeHTTP(w, r) // gọi handler tiếp theo
    })
}

func loggingMiddleware(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        start := time.Now()
        next.ServeHTTP(w, r)
        log.Printf("%s %s %v", r.Method, r.URL.Path, time.Since(start))
    })
}

// Chain middlewares — request đi từ ngoài vào trong
http.Handle("/api", loggingMiddleware(authMiddleware(apiHandler)))

// Gin middleware — đơn giản hơn
r := gin.Default()
r.Use(authMiddleware()) // áp dụng cho tất cả routes
api := r.Group("/api")
api.Use(rateLimitMiddleware()) // áp dụng cho group
```

a_en:
Middleware in Go is a wrapper function that receives a handler and returns a new handler, inserting logic before or after request processing.
```go
 // Basic middleware — stdlib net/http
func authMiddleware(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        token := r.Header.Get("Authorization")
        if !isValidToken(token) {
            http.Error(w, "Unauthorized", http.StatusUnauthorized)
            return
        }
        next.ServeHTTP(w, r) // call the next handler
    })
}

func loggingMiddleware(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        start := time.Now()
        next.ServeHTTP(w, r)
        log.Printf("%s %s %v", r.Method, r.URL.Path, time.Since(start))
    })
}

// Chain middlewares — request passes outside-in
http.Handle("/api", loggingMiddleware(authMiddleware(apiHandler)))

// Gin middleware — simpler registration
r := gin.Default()
r.Use(authMiddleware())        // applies to all routes
api := r.Group("/api")
api.Use(rateLimitMiddleware()) // applies to this group only
```

a:
Go sử dụng package `encoding/json`. Struct tags quyết định cách ánh xạ field sang JSON key.
```go
 // Định nghĩa struct với JSON tags
type User struct {
    Name  string `json:"name"`
    Age   int    `json:"age,omitempty"` // bỏ qua nếu zero value
    Email string `json:"-"`             // luôn bỏ qua khi encode
}

// Marshal — struct → JSON bytes
u := User{Name: "Alice", Age: 30}
data, err := json.Marshal(u)
// {"name":"Alice","age":30}

// Unmarshal — JSON bytes → struct
var u2 User
err = json.Unmarshal(data, &u2)

// HTTP response — dùng Encoder để stream
func handler(w http.ResponseWriter, r *http.Request) {
    w.Header().Set("Content-Type", "application/json")
    json.NewEncoder(w).Encode(User{Name: "Bob", Age: 25})
}

// HTTP request body — dùng Decoder
func createUser(w http.ResponseWriter, r *http.Request) {
    var u User
    if err := json.NewDecoder(r.Body).Decode(&u); err != nil {
        http.Error(w, err.Error(), http.StatusBadRequest)
        return
    }
}
```

a_en:
Go uses the `encoding/json` package. Struct tags control field-to-key mapping.
```go
 // Struct with JSON tags
type User struct {
    Name  string `json:"name"`
    Age   int    `json:"age,omitempty"` // omit if zero value
    Email string `json:"-"`             // always omit
}

// Marshal — struct → JSON bytes
u := User{Name: "Alice", Age: 30}
data, err := json.Marshal(u)
// {"name":"Alice","age":30}

// Unmarshal — JSON bytes → struct
var u2 User
err = json.Unmarshal(data, &u2)

// HTTP response — use Encoder to stream (preferred)
func handler(w http.ResponseWriter, r *http.Request) {
    w.Header().Set("Content-Type", "application/json")
    json.NewEncoder(w).Encode(User{Name: "Bob", Age: 25})
}

// HTTP request body — use Decoder
func createUser(w http.ResponseWriter, r *http.Request) {
    var u User
    if err := json.NewDecoder(r.Body).Decode(&u); err != nil {
        http.Error(w, err.Error(), http.StatusBadRequest)
        return
    }
}
```

a:
Graceful shutdown đợi các request đang xử lý hoàn thành trước khi thoát process, tránh mất data hoặc trả 502 cho client.
```go
srv := &http.Server{Addr: ":8080", Handler: mux}
go func() {
    if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
        log.Fatal(err)
}
}()

 // Bắt SIGINT / SIGTERM (Ctrl+C, kubectl rollout, docker stop)
quit := make(chan os.Signal, 1)
signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
<-quit

// Cho phép request đang chạy 30s để hoàn thành
ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
defer cancel()
if err := srv.Shutdown(ctx); err != nil {
    log.Fatalf("forced shutdown: %v", err)
}
```

a_en:
Graceful shutdown lets in-flight requests complete before the process exits — preventing data loss or 502 responses to clients.
```go
srv := &http.Server{Addr: ":8080", Handler: mux}
go func() {
    if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
        log.Fatal(err)
}
}()

 // Catch SIGINT / SIGTERM (Ctrl+C, kubectl rollout, docker stop)
quit := make(chan os.Signal, 1)
signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
<-quit

// Give in-flight requests up to 30s to finish
ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
defer cancel()
if err := srv.Shutdown(ctx); err != nil {
    log.Fatalf("forced shutdown: %v", err)
}
```

